<script setup lang="ts">
import { computed } from 'vue'
import { useDemoStore } from '../../stores/demo'
import { useOverlay } from '../../composables/useOverlay'
import CitationChip from './CitationChip.vue'
import type { Agent, Message } from '../../types/models'
const props=defineProps<{agent:Agent;message:Message}>(), emit=defineEmits<{suggest:[text:string];regenerate:[]}>(), store=useDemoStore(), ui=useOverlay()
const paragraphs=computed(()=>props.message.text.split('\n').map(p=>p.trim()).filter(Boolean).map(p=>p.split(/(【\d+】)/g)))
const citation=(text:string)=>/^【\d+】$/.test(text)
function cite(text:string) {const i=Number(text.slice(1,-1))-1, hit=props.message.hits?.[i];if(hit)ui.open({kind:'chunk',title:'原文片段',chunk:hit.chunk,doc:store.state.docs.find(d=>d.id===hit.chunk.docId),chunks:props.message.hits?.map(h=>h.chunk),index:i,query:store.state.lastQuery[props.agent.id]})}
function feedback(value:string) {props.message.feedback=props.message.feedback===value?'':value;store.notify(props.message.feedback?'感谢反馈，已记录到服务质量看板':'已取消反馈')}
</script>
<template><div class="msg" :class="{user:message.role==='user'}"><span v-if="message.role==='user'" class="msg-ava">张</span><span v-else class="msg-ava" :style="{'--tint':agent.tint,'--c':agent.color}"><AppIcon :name="agent.icon" :size="16"/></span><div class="msg-main"><div class="msg-head"><b>{{ message.role==='user'?'我':agent.name }}</b><span>{{ message.time }}</span></div><div class="bubble"><div v-if="message.status==='retrieving'" class="rag-status"><span class="spinner"></span> 正在检索知识库并召回相关片段…</div><div class="msg-text"><p v-for="(parts,i) in paragraphs" :key="i"><template v-for="(part,j) in parts" :key="j"><CitationChip v-if="citation(part) && !message.streaming" :index="Number(part.slice(1,-1))" @click="cite(part)"/><template v-else>{{ part }}</template></template></p></div><div v-if="message.welcome && message.chips?.length" class="msg-chips"><button v-for="q in message.chips" :key="q" class="suggest" :disabled="store.state.busy" @click="emit('suggest',q)">{{ q }}</button></div><div v-if="message.status==='generating'" class="rag-status"><span class="spinner"></span> 已命中 {{ message.hits?.length || 0 }} 条资料 · 正在生成回答</div><div v-else-if="!message.welcome && message.status==='done' && message.hits?.length" class="rag-status done"><AppIcon name="check" :size="11"/> 答案引用了 {{ message.hits.length }} 条知识库原文，点击编号可核对出处</div></div><div v-if="message.role==='assistant' && !message.welcome && !message.streaming" class="msg-tools"><button :class="{on:message.feedback==='up'}" :aria-pressed="message.feedback==='up'" @click="feedback('up')"><AppIcon name="thumb" :size="12"/> 有帮助</button><button :class="{on:message.feedback==='down'}" :aria-pressed="message.feedback==='down'" @click="feedback('down')"><AppIcon name="thumb" :size="12"/> 需改进</button><button :disabled="store.state.busy" @click="emit('regenerate')"><AppIcon name="refresh" :size="12"/> 重新生成</button></div></div></div></template>
